"""Build offline, verified in-place Agency Flash installer from the inspected source and module code."""
from pathlib import Path
import re,base64,json
r=Path(__file__).resolve().parent.parent
full=(r/'GC_NH_Cockpit_Daily_Labour_Phase2.html').read_text()
def body(id):
 m=re.search(r'<script id="'+id+r'"(?: type="application/json")?>([\s\S]*?)</script>',full)
 assert m,id
 return m[1]
payload={i:body(i) for i in ['daily-agency-seed','daily-agency-engine','daily-labour-module']}
encoded=base64.b64encode(json.dumps(payload,separators=(',',':')).encode()).decode()
html='''<!DOCTYPE html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Install Agency Flash into the same cockpit file</title><style>body{font:16px/1.55 Arial,sans-serif;background:#f2f6f3;color:#193b2b;margin:0;padding:24px}main{max-width:790px;margin:auto;background:#fff;border:1px solid #ccdacf;border-radius:13px;padding:26px}h1{font-size:24px}button{border:0;border-radius:7px;background:#176b48;color:white;font-weight:700;padding:12px 18px;margin:8px 8px 8px 0;cursor:pointer}button:disabled{opacity:.5}#status{white-space:pre-wrap;background:#ecf4ed;padding:14px;border-radius:7px}</style></head><body><main><h1>Connect agency estimates to your existing cockpit</h1><p>Installs the supplied J&T and Quest allocations and 8-hour provisional Flash calculation into the HTML file you choose. Your roster, Crown hours, role corrections, Prep KG, complaints, PO and other saved cockpit data stay in that same file.</p><ol><li>In your working cockpit, click <b>Save</b> and check that the latest changes are in the HTML file. Keep that tab open and pause auto-save while updating.</li><li>Click <b>Choose existing cockpit and install Agency Flash</b>. Select the saved Phase 2 master HTML and allow editing.</li><li>After verification, reopen the same file. Go to Daily Labour / UPLH and check the 13 October Flash UPLH and agency rows. Save once more when you make later edits.</li></ol><p>The updater saves the entire previous file in this browser before opening a writer and checks the written file after closing it. No new dashboard copy is downloaded automatically.</p><button id="install">Choose existing cockpit and install Agency Flash</button><button id="previous">Download previous file</button><p id="status" role="status">Ready. Your existing cockpit file is changed in place after its data blocks are checked.</p></main><script>
const payload=JSON.parse(atob('__PAYLOAD__'));
function blocks(s){return new Map([...s.matchAll(/<script\\b([^>]*)>([\\s\\S]*?)<\\/script\\s*>/gi)].filter(m=>/type=["']application\\//i.test(m[1])).map(m=>[m[1].match(/\\bid=["']([^"']+)/)[1],m[0]]));}
function patch(s){if(!s.includes('id="daily-efficiency-engine"')||!s.includes('id="daily-labour-module"'))throw Error('Select your saved Agency Flash cockpit with Daily Labour and Efficiency.');if(s.includes('id="daily-agency-engine"'))throw Error('Agency Flash is already installed in this file.');const before=blocks(s),old=/<script id="daily-labour-module">[\\s\\S]*?<\\/script>/g;if([...s.matchAll(old)].length!==1)throw Error('Daily Labour module must appear exactly once.');const addition='<script id="daily-agency-seed" type="application/json">'+payload['daily-agency-seed']+'</'+'script>\\n'+'<script id="daily-agency-engine">'+payload['daily-agency-engine']+'</'+'script>\\n'+'<script id="daily-labour-module">'+payload['daily-labour-module']+'</'+'script>';const html=s.replace(old,()=>addition),after=blocks(html);for(const [id,source]of before)if(after.get(id)!==source)throw Error('Existing data block '+id+' changed.');return {html,blocks:before.size};}
function backupDB(){return new Promise((res,rej)=>{const q=indexedDB.open('cockpit-agency-installer-backups',1);q.onupgradeneeded=()=>q.result.createObjectStore('versions');q.onsuccess=()=>res(q.result);q.onerror=()=>rej(q.error);});}
async function previous(){const db=await backupDB();try{return await new Promise((res,rej)=>{const q=db.transaction('versions').objectStore('versions').get('latest');q.onsuccess=()=>res(q.result);q.onerror=()=>rej(q.error);});}finally{db.close();}}
async function backup(blob,name){const db=await backupDB();try{await new Promise((res,rej)=>{const tx=db.transaction('versions','readwrite');tx.objectStore('versions').put({blob,name,at:new Date().toISOString()},'latest');tx.oncomplete=res;tx.onerror=()=>rej(tx.error);tx.onabort=()=>rej(tx.error||Error('Backup cancelled'));});}finally{db.close();}const test=await previous();if(test?.blob?.size!==blob.size)throw Error('Previous-file backup could not be verified; writer not opened.');}
async function install(handle){if(await handle.queryPermission({mode:'readwrite'})!=='granted'&&await handle.requestPermission({mode:'readwrite'})!=='granted')throw Error('File edit permission not granted.');const file=await handle.getFile();if(!file.size)throw Error('Selected cockpit is empty.');const text=await file.text(),result=patch(text),output=new Blob([result.html],{type:'text/html'});await backup(new Blob([text],{type:'text/html'}),handle.name);const check=await handle.getFile();if(check.size!==file.size||check.lastModified!==file.lastModified)throw Error('The cockpit changed while preparing the update. No writer opened.');const writer=await handle.createWritable();try{await writer.write(output);await writer.close();}catch(e){try{await writer.abort();}catch(_){}throw e;}const after=await handle.getFile();if(after.size!==output.size||await after.text()!==result.html)throw Error('Written cockpit could not be verified. Keep the working tab open and use Download previous file.');return{name:handle.name,bytes:after.size,blocks:result.blocks};}
window.CockpitAgencyInstaller={patch,install};const status=document.getElementById('status'),button=document.getElementById('install');button.onclick=async()=>{if(typeof showOpenFilePicker!=='function'){status.textContent='Open this installer in Edge or Chrome, where direct file editing is available.';return;}button.disabled=true;try{const [handle]=await showOpenFilePicker({multiple:false,types:[{description:'Cockpit HTML',accept:{'text/html':['.html','.htm']}}]});const x=await install(handle);status.textContent='Agency Flash installed and verified in '+x.name+'. '+x.blocks+' original data blocks preserved. Reopen that same file and check Daily Labour / UPLH. No extra cockpit file was created.';}catch(e){status.textContent=e.name==='AbortError'?'Cancelled; no file changed.':'Update failed: '+e.message+' Keep your working tab open. If a write began, use Download previous file.';}finally{button.disabled=false;}};
document.getElementById('previous').onclick=async()=>{try{const x=await previous();if(!x)throw Error('No previous file retained yet.');const url=URL.createObjectURL(x.blob),a=document.createElement('a');a.href=url;a.download=x.name.replace(/\\.html?$/i,'')+'_PREVIOUS.html';document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),30000);}catch(e){status.textContent=e.message;}};
</script></body></html>'''.replace('__PAYLOAD__',encoded)
(r/'Cockpit_Agency_Flash_InPlace_Updater.html').write_text(html)
print('Built',len(html),'bytes')
